const raw=$input.first()?.json?.body;
if(!raw||typeof raw!=='object'||Array.isArray(raw)||Object.keys(raw).some(k=>!['jwt','request','requestId'].includes(k)))throw Error('Only a signed-in structured staff request is supported');
const jwt=raw.jwt,r=raw.request;
if(!raw.requestId?.startsWith('ORIGINAL_STAFF_TEST_')||r?.origin!=='LUN'||r?.destination!=='DXB'||r?.tripType!=='ONE_WAY'||r?.adults!==1||r?.children!==0||r?.infants!==0||r?.cabin!=='ECONOMY'||r?.preference!=='BEST')throw Error('Fictional staging fixture only');
const requestId=raw.requestId;
if(typeof requestId!=='string'||!/^[A-Za-z0-9_-]{12,64}$/.test(requestId))throw Error('Stable requestId required to prevent duplicate processing');
if(typeof jwt!=='string'||jwt.length<100||jwt.length>5000||!/^eyJ[A-Za-z0-9._-]+$/.test(jwt))throw Error('Valid reviewer session required');
if(!r||typeof r!=='object'||Array.isArray(r))throw Error('Structured travel request required');
const keys=['origin','destination','departureDate','returnDate','tripType','adults','children','infants','cabin','preference'];
if(Object.keys(r).some(k=>!keys.includes(k)))throw Error('Customer data or unsupported fields prohibited');
const date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v;
if(!/^[A-Z]{3}$/.test(r.origin||'')||!/^[A-Z]{3}$/.test(r.destination||'')||r.origin===r.destination)throw Error('Invalid route');
if(!date(r.departureDate)||r.departureDate<new Date().toISOString().slice(0,10)||!['ONE_WAY','ROUND_TRIP'].includes(r.tripType))throw Error('Invalid departure/trip');
if(r.tripType==='ONE_WAY'&&r.returnDate!==null||r.tripType==='ROUND_TRIP'&&(!date(r.returnDate)||r.returnDate<=r.departureDate))throw Error('Invalid return');
if(!['ECONOMY','PREMIUM_ECONOMY','BUSINESS','FIRST'].includes(r.cabin)||!['BEST','CHEAPEST','FASTEST','FEWEST_STOPS'].includes(r.preference))throw Error('Invalid options');
if(!['adults','children','infants'].every(k=>Number.isInteger(r[k]))||r.adults<1||r.adults>9||r.children<0||r.children>8||r.infants<0||r.infants>r.adults||r.adults+r.children>9)throw Error('Invalid passengers');
return [{json:{jwt,requestId,request:Object.fromEntries(keys.map(k=>[k,r[k]]))}}];

const members=$input.all().map(i=>i.json);if(members.length!==1||!members[0]?.user_id)throw Error('Unauthorized reviewer');
const x=$('Allowlist AI1 Request').first().json.request;
return [{json:{request:x,mode:'GDS_PLAN_DRY_RUN',provider:'NOT_CONNECTED',canRunCommands:false,canBook:false,canQuote:false,availableIntegrations:[],instructions:'Produce a safe research checklist and integration readiness. No vendor specific cryptic commands.'}}];

const value=$input.first()?.json?.output;
const raw=typeof value==='string'?value.trim():'';
const prohibit=/\b(?:sell\s+[0-9]|SS[0-9]|FXP|TTP|ER\s*$|PNR\s+[A-Z0-9]{6}|booking confirmed|ticket issued|payment received|live prices|available seats verified|supplier|wholesale|markup|commission|margin)\b/i;
const safe=raw.length>=35&&raw.length<=2400&&!prohibit.test(raw)?raw:'GDS RESEARCH PLAN — NOT CONNECTED. Verify the authorized provider and integration documentation before generating or running vendor-specific commands. Confirm route, dates, passengers, cabin, fare rules, baggage, and reprice/approval steps. No search, pricing, reservation, or ticketing occurred.';
return [{json:{ok:true,mode:'AWAITING_GDS_CONNECTION',providerConnected:false,commandExecutionAllowed:false,customerSendAllowed:false,bookingAvailable:false,ticketIssuanceAllowed:false,plan:safe}}];

const x=$input.first()?.json||{};
if(x.ok!==true||x.mode!=='AWAITING_GDS_CONNECTION'||x.providerConnected!==false||x.commandExecutionAllowed!==false||x.customerSendAllowed!==false||x.bookingAvailable!==false||x.ticketIssuanceAllowed!==false||typeof x.plan!=='string'||x.plan.length>2500||!x.plan.startsWith('GDS RESEARCH PLAN — NOT CONNECTED'))throw Error('AI2 safety gate rejected');
if(/\b(?:TTP|FXP|ticket issued|booking confirmed|payment received|supplier|wholesale|markup|commission)\b/i.test(x.plan))throw Error('Unsafe content');
return [{json:{ok:true,stage:'AI1_TO_AI2_INTERNAL_HANDOFF_DEMO',handoffCompleted:true,providerConnected:false,customerSendAllowed:false,customerQuoteAvailable:false,bookingAvailable:false,ticketIssuanceAllowed:false,plan:x.plan,note:'Internal transfer only. No WhatsApp, GDS, real quotation or booking.'}}];

const c=$input.first()?.json||{};
if(c.completed!==true)throw Error('Could not persist handoff completion');
const plan=$('Enforce AI2 Read-Only Safety Gate').first().json;
if(plan.ok!==true||plan.customerSendAllowed!==false||plan.providerConnected!==false||plan.handoffCompleted!==true)throw Error('Internal plan safety flags invalid');
return [{json:{...plan,status:'COMPLETED'}}];

const x=$input.first()?.json||{};
if(!['DUPLICATE_COMPLETED','DUPLICATE_IN_PROGRESS','CONFLICT','RETRY_LIMIT_REACHED'].includes(x.action))throw Error('Unexpected idempotency response');
return [{json:{ok:!['CONFLICT','RETRY_LIMIT_REACHED'].includes(x.action),stage:'AI1_TO_AI2_INTERNAL_HANDOFF_DEMO',status:x.action,handoffCompleted:false,duplicate:!['CONFLICT','RETRY_LIMIT_REACHED'].includes(x.action),providerConnected:false,customerSendAllowed:false,customerQuoteAvailable:false,bookingAvailable:false,ticketIssuanceAllowed:false,note:x.action==='CONFLICT'?'Same ID used with changed travel details. Reject and investigate.':x.action==='RETRY_LIMIT_REACHED'?'Retry limit reached; staff investigation required.':'Already received; AI2 was not called again.'}}];
